#!/usr/bin/bash

# backup_emmc.sh
# AURKNIX eMMC Backup Script
# This script backs up the whole eMMC disk to /storage/roms/emmc_bak/emmc_backup.img.

set -e

# ==========================================
# Set up Display Variables
# ==========================================
export XDG_RUNTIME_DIR=/var/run/0-runtime-dir
export WAYLAND_DISPLAY=wayland-1
export DISPLAY=:0.0

# ==========================================
# Base64 Embedded Images
# ==========================================
echo "" | base64 -d > /tmp/backup_prompt.png
echo "" | base64 -d > /tmp/backing_up.png
echo "" | base64 -d > /tmp/backup_success.png
echo "" | base64 -d > /tmp/backup_failed.png

show_image() {
    local img=$1
    set +e
    killall -9 mpv 2>/dev/null
    set -e
    if [ -f "/tmp/$img" ]; then
        mpv --loop-file=inf --fullscreen --no-terminal "/tmp/$img" >/dev/null 2>&1 &
    fi
}

cleanup_on_error() {
    echo "An error occurred during backup!"
    show_image "backup_failed.png"
    sleep 10
}

confirm_backup_emmc() {
    show_image "backup_prompt.png"
    echo "============================================="
    echo "This will back up eMMC to /storage/roms/emmc_bak/emmc_backup.img."
    echo "Existing backup image at that path will be overwritten."
    echo "Press A to continue, or press B to return."
    echo "============================================="

    local event_type="EV_KEY"
    local event_btn_a="BTN_EAST"
    local event_btn_b="BTN_SOUTH"
    local event_dev=""
    local joystick_dev=""
    local reply=""

    if [ -e /dev/input/by-path/platform-*event-joystick ]; then
        joystick_dev=$(eval echo /dev/input/by-path/platform-*event-joystick)
        if [ -e "$joystick_dev" ]; then
            event_dev=$(readlink -f "$joystick_dev")
        fi
    fi

    if [ -z "$event_dev" ]; then
        echo "No gamepad detected. Falling back to terminal input."
        while true; do
            read -p "Press A to continue, or B to return: " -n 1 -r reply
            echo
            case "$reply" in
                [Aa])
                    echo "Continuing with eMMC backup..."
                    return 0
                    ;;
                [Bb])
                    echo "Backup cancelled."
                    return 1
                    ;;
                *)
                    echo "Invalid input. Press A to continue, or B to return."
                    ;;
            esac
        done
    fi

    echo "Waiting for gamepad input... Press A (East) to continue, B (South) to return."
    while true; do
        if evtest --query "$event_dev" "$event_type" "$event_btn_a"; then
            :
        elif [ $? -eq 10 ]; then
            echo "Button A pressed. Continuing with eMMC backup..."
            return 0
        fi
        if evtest --query "$event_dev" "$event_type" "$event_btn_b"; then
            :
        elif [ $? -eq 10 ]; then
            echo "Button B pressed. Backup cancelled."
            return 1
        fi
        sleep 0.1
    done
}

trap cleanup_on_error ERR

echo "=== AURKNIX eMMC Backup Script ==="

EMMC_DISK="/dev/mmcblk0"
BACKUP_DIR="/storage/roms/emmc_bak"
BACKUP_FILE="$BACKUP_DIR/emmc_backup.img"

if [ ! -b "$EMMC_DISK" ]; then
    echo "Error: Could not find eMMC disk at $EMMC_DISK"
    exit 1
fi

if ! confirm_backup_emmc; then
    trap - ERR
    killall -9 mpv 2>/dev/null || true
    exit 0
fi

mkdir -p "$BACKUP_DIR"
show_image "backing_up.png"

echo "Source (eMMC): $EMMC_DISK"
echo "Backup Image: $BACKUP_FILE"
echo "Starting backup... This may take a few minutes. Please do not power off."

dd if="$EMMC_DISK" of="$BACKUP_FILE" bs=4M
sync

trap - ERR

echo "============================================="
echo "Backup complete!"
echo "The eMMC has been backed up to $BACKUP_FILE."
echo "============================================="

show_image "backup_success.png"
sleep 5
killall -9 mpv 2>/dev/null
